    ('B','X3'):45.0,
    ('N_d1','N_d2'):15.0,
    ('N_d1','X3'):10.0,
    ('N_d2','X3'):25.0,
}
# make symmetric
meas = {tuple(sorted(k)):v for k,v in meas.items()}

def path_resistance(tree_edges, start, end):
    # tree edges dict with resistance variables unknown; we will compute symbolic sum of edges along path
    # We'll just return list of edge identifiers in path
    # Build adjacency
    adj = {n:[] for n in nodes}
    for e in tree_edges:
        a,b = e
        adj[a].append(b)
        adj[b].append(a)
    # BFS to find path
    from collections import deque
    q=deque([(start, [])])
    visited=set([start])
    while q:
        cur, path = q.popleft()
        if cur==end:
            return path
        for nb in adj[cur]:
            if nb not in visited:
                visited.add(nb)
                q.append((nb, path+[ (cur, nb) ]))
    return None

solutions=[]
for edges in itertools.combinations(all_edges,3):
    # check connectivity (spanning tree) using union-find
    parent={n:n for n in nodes}
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb:
            parent[rb]=ra
    for a,b in edges:
        union(a,b)
    roots={find(n) for n in nodes}
    if len(roots)!=1:
        continue
    # also ensure no cycles (3 edges with 4 nodes automatically no cycle if connected)
    # set up linear equations: each edge has variable R_e
    edge_vars = {e: f'R{idx}' for idx,e in enumerate(edges)}
    # Build equations: for each measurement, sum of R along path = measured
    equations=[]
    for (u,v),val in meas.items():
        path = path_resistance(edges, u, v)
        if path is None:
            break
        coeffs = {e:0 for e in edges}
        for a,b in path:
            e = tuple(sorted((a,b)))
            coeffs[e] += 1
        equations.append((coeffs, val))
    else:
        # solve linear system
        # matrix
        import numpy as np
        m=len(equations)
        n=len(edges)
        A=np.zeros((m,n))
        b=np.zeros(m)
        edge_list=list(edges)
        for i,(coeffs,val) in enumerate(equations):
            for j,e in enumerate(edge_list):
                A[i,j]=coeffs[e]
            b[i]=val
        # solve least squares
        try:
            sol, residuals, rank, s = np.linalg.lstsq(A,b,rcond=None)
        except Exception as e:
            continue
        # check if solution satisfies exactly (within tolerance) and all positive
        if np.allclose(A.dot(sol), b, atol=1e-6) and np.all(sol>0):
            solutions.append((edges, sol))

print('found', len(solutions), 'solutions')
for edges, sol in solutions:
    print(edges)
    for e,r in zip(edges, sol):
        print(e, r)
    print('---')
